// 解析 argv（已去掉 node 与前两个参数）。目前只认 --name。
export function parseArgs(argv) {
  const out = { name: null, verbose: false, rest: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--name") out.name = argv[++i] ?? null;
    else out.rest.push(a);
  }
  return out
}

import test from "node:test";
import assert from "node:assert/strict";
import { parseArgs } from "../src/parse-args.js";

test("--name 取值", () => {
  assert.equal(parseArgs(["--name", "x"]).name, "x");
});
// 待实现：--verbose 打开 verbose，且不进 rest
test("--verbose 置位且不进 rest", () => {
  const r = parseArgs(["--verbose", "--name", "x"]);
  assert.equal(r.verbose, true);
  assert.deepEqual(r.rest, []);
});
test("--verbose 与位置参数共存", () => {
  const r = parseArgs(["a", "--verbose"]);
  assert.equal(r.verbose, true);
  assert.deepEqual(r.rest, ["a"]);
});

let verbose = false;

export function setVerbose(v) { verbose = v; }
export function isVerbose() { return verbose; }

// verbose 关时静默，开时打到 stderr
export function debug(msg) {
  if (verbose) process.stderr.write(`[debug] ${msg}\n`);
}

import test from "node:test";
import assert from "node:assert/strict";
import { setVerbose, isVerbose } from "../src/logger.js";
import { parseArgs } from "../src/parse-args.js";

// 待实现：解析出来的 verbose 要能喂给 logger
test("parseArgs 的结果可以直接喂 setVerbose", () => {
  const r = parseArgs(["--verbose"]);
  setVerbose(r.verbose);
  assert.equal(isVerbose(), true);
  setVerbose(false);
  assert.equal(isVerbose(), false);
});

